window.GLYPH_STORIES = {
  安: { headline: '屋檐之下，安居的想象。' },
  宇: { headline: '从房檐，到宇宙。' },
  光: { headline: '把光亮，举过头顶。' },
  包: { headline: '一个字，藏着包裹的形状。' },
  窗: { headline: '透过一个字，看见一扇窗。' },
  先: { headline: '走在前面，就成了「先」。' },
  男: { headline: '田与力，写进同一个字。' },
  "06592_一_Z_說文‧一部": {"headline": "一就是一横，简单又直接。", "original_meaning": "一，是万物的起点。古人认为天地刚开始形成时，大道就立在'一'上，由一分化出天地，再化育出万物。", "structure_desc": "在甲骨文和金文里，'一'就是一横，用一横来表示数字'一'。古人后来还造过一个繁写体'弌'，在'一'上加了'弋'当声符，但因为'弋'的笔画容易和'戈'混在一起，最后还是用回了最简单的一横。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「一」條；香港中文大學《漢語多功能字庫》「一」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%80（2026-11-03 查閱）"},
  "06601_三_Z_說文‧三部": {"headline": "三横排排坐，就是三。", "original_meaning": "三，代表天、地、人三者。", "structure_desc": "甲骨文和金文里，'三'就是三横。古人把一到四都用横画来表示：一横是一，两横是二，三横是三，四横是四。学者徐中舒认为这些横画其实是古代计数用的小木棍（算筹）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「三」條；香港中文大學《漢語多功能字庫》「三」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%89（2026-11-03 查閱）"},
  "06602_上_Z_小篆": {"headline": "短横画在长横上，就是「上」。", "original_meaning": "上，指位置在高处。古人用一个符号来指明「上面」这个方位。", "structure_desc": "最早的「上」字，是在一条弧线（后来刻成直线）上面加一短横，用短横所在的位置来表示「上面」的意思。早期甲骨文和金文里，「上」写作两横的样子，和「二」很像，容易和数字「二」以及「下」搞混。所以到了春秋晚期，人们多加了一竖笔，写成了现在的「上」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「丄」條（今字作「上」）；香港中文大學《漢語多功能字庫》「上」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%8A（2026-11-03 查閱）"},
  "06603_下_Z_小篆": {"headline": "短横画在长横下，就是「下」。", "original_meaning": "下，指位置在低处，和「上」相对。", "structure_desc": "最早的「下」字，是在一条弧线（后来刻成直线）下面加一短横，用短横所在的位置来表示「下面」的意思。早期甲骨文和金文里，「下」写作两横的样子，容易和「上」以及数字「二」搞混。所以到了春秋晚期，人们多加了一竖笔，写成了现在的「下」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「丅」條（今字作「下」）；香港中文大學《漢語多功能字庫》「下」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%8B（2026-11-03 查閱）"},
  "06605_不_Z_說文‧不部": {"headline": "「不」本来画的是植物的根须。", "original_meaning": "「不」本来指植物的根须，后来被借来表示否定的意思。", "structure_desc": "关于「不」字的来历有两种说法。一种认为上面的横画代表地面，下面的笔画像植物扎在土里的根须，所以「不」原本就是草根的意思。另一种说法认为「不」像花朵底部的花萼。不管哪种说法，「不」原本是个表示具体事物的字，后来被借来专门表示否定的意思，一直用到现在。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「不」條；香港中文大學《漢語多功能字庫》「不」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%8D（2026-11-03 查閱）"},
  "06606_与_Z_說文‧勺部": {"headline": "两只手互相递东西，就是「与」。", "original_meaning": "「与」的本义是给予、赐予，就是把东西交给别人。", "structure_desc": "金文的「与」字，画的是两个人（上面两只手和下面两只手）互相交付牙齿的样子。古人有赠送牙齿的习俗，所以用「递牙齿」来表示「给予」的意思。直到今天，一些少数民族还保留着类似的风俗。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「與」條；香港中文大學《漢語多功能字庫》「與」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%88%87（2026-11-03 查閱）"},
  "06618_业_Z_小篆": {"headline": "「业」原来是挂钟磬的木架子。", "original_meaning": "「业」指古代悬挂钟和磬的架子上面那块带锯齿的大木板。", "structure_desc": "「业」字的形状，像两个并排站立的铜人举着一根横木，横木上挂着钟和磬。所以「业」本来指的是古代悬挂乐器的架子，架子上的木板边缘刻成锯齿状，用来挂钟和磬。后来「业」引申出事业、学业等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「業」條；香港中文大學《漢語多功能字庫》「業」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A5%AD（2026-11-03 查閱）"},
  "06628_两_Z_小篆": {"headline": "「两」本来画的是车前套牲口的两根直木。", "original_meaning": "「两」本来指古代马车前面套牲口的两根直木（车轭），后来表示成双成对的意思。", "structure_desc": "「两」字是从古代「车」字里截取一部分造出来的，画的是马车辕木前端横杠上系着的两根套牲口的直木。因为这两根直木是成对出现的，所以「两」就有了「成双」「两个」的意思。后来又用作重量单位。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「兩」條；香港中文大學《漢語多功能字庫》「兩」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%A9（2026-11-03 查閱）"},
  "06637_中_Z_說文‧丨部": {"headline": "「中」画的是古代测风向的旗杆。", "original_meaning": "「中」指中央、中间，就是方位上不偏不倚的位置。", "structure_desc": "甲骨文的「中」字，画的是一根长杆子，杆子的上部、下部或上中下都挂着飘带。这其实是古代测量风向的工具。因为测风向的杆子要立在中心位置，所以「中」就有了「中央」「中间」的意思。后来又引申出「中等」「适中」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「中」條；香港中文大學《漢語多功能字庫》「中」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%AD（2026-11-03 查閱）"},
  "06650_为_Z_小篆": {"headline": "一只手牵着大象干活，就是「为」。", "original_meaning": "「为」的本义是做事、作为。古人驯养大象来干活，所以用「手牵大象」来表示做事。", "structure_desc": "甲骨文和金文的「为」字，画的是一只手牵着一头大象。商朝的时候，人们驯养大象来帮忙干活，所以用「手牵大象」这个形象来表示「做事」的意思。后来「为」又引申出「作为」「成为」等意思，还经常用作虚词。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「爲」條（今字作「為」）；香港中文大學《漢語多功能字庫》「為」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%82%BA（2026-11-03 查閱）"},
  "06651_主_Z_說文‧丶部": {"headline": "「主」原来画的是祭祀用的牌位。", "original_meaning": "「主」指古代祭祀时供奉的牌位，也指灯盏里的火芯。", "structure_desc": "甲骨文的「主」字，画的是祭祀用的牌位形状。「主」和「示」本来是同一个字，后来才分开。「主」本来指祭祀的牌位，牌位代表祖先，所以引申出「主人」「主要」的意思。另外，「主」也指灯盏里的火芯，就是灯炷，后来另造了「炷」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「主」條；香港中文大學《漢語多功能字庫》「主」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%BB（2026-11-03 查閱）"},
  "06664_么_Z_小篆": {"headline": "「么」就是细小、微小的意思。", "original_meaning": "「么」（麽）的本义是细小、微小。", "structure_desc": "「么」是「麽」的简写，本义是细小、微小。比如古书里说的「麽虫」，就是指很小的虫子。后来「么」多用作词尾，比如「什么」「这么」「那么」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「麼」條；香港中文大學《漢語多功能字庫》「麼」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%BA%BC（2026-11-03 查閱）"},
  "06667_之_Z_說文‧之部": {"headline": "一只脚离开地面往前走，就是「之」。", "original_meaning": "「之」的本义是前往、到……去。", "structure_desc": "甲骨文的「之」字，上面是一只脚（「止」），下面一横代表地面。合起来表示脚从地面上迈出去，前往某个地方。后来「之」多用作虚词，比如「之间」「之后」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「之」條；香港中文大學《漢語多功能字庫》「之」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%8B（2026-11-03 查閱）"},
  "06687_也_Z_說文‧𠂆部": {"headline": "「也」字画的是嘴里呼出的气。", "original_meaning": "「也」是语气词，表示停顿或肯定的语气。", "structure_desc": "金文的「也」字，上面是「口」，下面是一弯弯曲曲的竖画，像从嘴里呼出来的气。「也」本来就是用来表示语气停顿的，相当于现在说的「啊」「呢」。后来经常用在句末，表示肯定或感叹的语气。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「也」條；香港中文大學《漢語多功能字庫》「也」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%9F（2026-11-03 查閱）"},
  "06726_了_Z_說文‧了部": {"headline": "「了」字画的是手腿弯曲的样子。", "original_meaning": "「了」的本义是弯曲，引申为完结、结束。", "structure_desc": "「了」字画的是一个孩子没有手臂、手脚弯曲的样子，本义是弯曲。因为做事做到最后手脚都弯下来了，所以引申出「完结」「结束」的意思，比如「完了」「了结」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「了」條；香港中文大學《漢語多功能字庫》「了」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%86（2026-11-03 查閱）"},
  "06731_事_Z_說文‧史部": {"headline": "「事」画的是手里拿着打猎的工具。", "original_meaning": "「事」指职务、工作，就是要做的事情。", "structure_desc": "甲骨文的「事」字，是一只手拿着一个打猎用的工具。后来这个字形分化出了「史」「吏」「事」「使」四个字，它们原本是同一个字。其中「事」专门用来表示「职务」「事情」的意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「事」條；香港中文大學《漢語多功能字庫》「事」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%8B（2026-11-03 查閱）"},
  "06734_于_Z_說文‧于部": {"headline": "「于」本来画的是古代的乐器竽。", "original_meaning": "「于」本来指古代的管乐器竽，后来借用作虚词，表示在、到、对的意思。", "structure_desc": "「于」字的来历有两种说法。一种认为甲骨文画的是管状乐器竽的形状，竽是把很多根竹管并在一起做成的乐器。后来为了书写方便，简化成了「于」字。再后来「于」被借用作虚词，表示「在」「到」「对」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「亏」條（今字作「于」）；香港中文大學《漢語多功能字庫》「于」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%8E（2026-11-03 查閱）"},
  "06747_些_Z_說文‧此部": {"headline": "「些」表示少量、一点点。", "original_meaning": "「些」的本义是少量、少许。", "structure_desc": "「些」字从「此」从「二」，本义是少量、少许。比如「一些」「些许」，都是表示数量不多的意思。在古代楚辞里，「些」还用作句末的语气词。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「些」條；香港中文大學《漢語多功能字庫》「些」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%9B（2026-11-03 查閱）"},
  "06759_产_Z_小篆": {"headline": "「产」就是生出来、造出来的意思。", "original_meaning": "「产」的本义是出生、生产。", "structure_desc": "「产」的繁体字是「產」，从「生」，表示出生的意思。「产」本来指生孩子，后来引申为生产、制造、出产等意思，比如「产物」「产量」「特产」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「産」條（今字作「產」）；香港中文大學《漢語多功能字庫》「產」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%A2（2026-11-03 查閱）"},
  "06778_人_Z_說文‧人部": {"headline": "「人」画的是一个人侧身站着的样子。", "original_meaning": "「人」指人类，是天地间最尊贵的生物。", "structure_desc": "古文字的「人」字，画的是一个人侧身站立、双手下垂的样子，上面是头和手臂，下面是腿。古人认为人是天地间最尊贵的生物，所以用一个简单的人形来表示。「人」和「千」本来是同一个字，后来才分开。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「人」條；香港中文大學《漢語多功能字庫》「人」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%BA（2026-11-03 查閱）"},
  "06784_什_Z_說文‧人部": {"headline": "「什」就是以十个人为一组。", "original_meaning": "「什」指以十为单位，古代十家或十人为一「什」。", "structure_desc": "「什」从「人」从「十」，本义是以十为单位。古代十家组成一「什」，互相担保；军队里十个人也组成一「什」。后来「什」引申为各种杂样的意思，比如「什物」就是各种日用物品，「什锦」就是多种花样的。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「什」條；香港中文大學《漢語多功能字庫》「什」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%80（2026-11-03 查閱）"},
  "06798_从_Z_說文‧从部": {"headline": "两个人一前一后跟着走，就是「从」。", "original_meaning": "「从」的本义是跟随、跟从。", "structure_desc": "甲骨文和金文的「从」字，是两个人一前一后跟着走的样子，本义是跟随。后来人们在「从」的基础上加了表示行走的「辵」旁，造出了「從」字。现在的简化字又把它简化回了「从」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「从」條；香港中文大學《漢語多功能字庫》「从」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%8E（2026-11-03 查閱）"},
  "06806_他_Z_小篆": {"headline": "「他」指别的人或事物。", "original_meaning": "「他」是代词，指别的、其他的，也用来指第三方。", "structure_desc": "「他」在甲骨文和金文里都没有出现，是个比较晚才有的字。它本来是个代词，指「别的」「其他的」，比如「其他」「他乡」。后来也用来指代第三方的人或事物。在古代，「他」可以指代男、女和一切东西，专门用来指男性是现代汉语才有的用法。", "source": "香港中文大學《漢語多功能字庫》「他」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%96（2026-11-03 查閱）；《說文解字》未收此字"},
  "06821_以_Z_說文‧巳部": {"headline": "「以」画的是用手提着东西。", "original_meaning": "「以」的本义是用手拿着、提着，后来多用作虚词。", "structure_desc": "甲骨文的「以」字，画的是一个人用手提着一样东西，本义是拿、用。后来「以」多借用作虚词，表示「用」「凭借」「因为」等意思，比如「以一当十」「以理服人」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「㠯」條（今字作「以」）；香港中文大學《漢語多功能字庫》「以」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%A5（2026-11-03 查閱）"},
  "06874_会_Z_小篆": {"headline": "「会」画的是用盖子把器皿盖起来。", "original_meaning": "「会」的本义是相合、合拢，引申为聚会、会合。", "structure_desc": "甲骨文和金文的「会」字，上面是盖子，下面是器皿，中间装着东西，合起来表示用盖子把器皿盖好，本义是相合。后来引申出「聚会」「会合」「会议」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「會」條；香港中文大學《漢語多功能字庫》「會」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%83（2026-11-03 查閱）"},
  "06918_但_Z_說文‧人部": {"headline": "「但」本来指脱掉上衣露出身体。", "original_meaning": "「但」的本义是脱去上衣、露出身体，后来多用作转折连词。", "structure_desc": "「但」从「人」，「旦」声。本义是指人没有穿上衣，露出身体，这个意思后来多写作「袒」。再后来「但」被借用作转折连词，相当于「不过」「但是」，比如「他很累，但还是坚持工作」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「但」條；香港中文大學《漢語多功能字庫》「但」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%86（2026-11-03 查閱）"},
  "06931_体_Z_小篆": {"headline": "「体」指人的身体。", "original_meaning": "「体」（體）的本义是人的身体。", "structure_desc": "「体」的繁体字是「體」，从「骨」，本义是人的身体。「體」字出现得比较晚，早期有的从「身」，有的从「肉」，后来才统一成从「骨」的写法。现在简化为「体」，从「人」从「本」，表示身体是人的根本。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「體」條；香港中文大學《漢語多功能字庫》「體」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%AB%94（2026-11-03 查閱）"},
  "06940_作_Z_說文‧人部": {"headline": "「作」就是开始做、站起来干。", "original_meaning": "「作」的本义是起来、开始做。", "structure_desc": "「作」从「人」从「乍」，本义是起来、开始做事。古代一般写作「乍」，后来加了「人」旁变成「作」。「作」有做、制作、兴起等意思，比如「工作」「创作」「振作」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「作」條；香港中文大學《漢語多功能字庫》「作」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%9C（2026-11-03 查閱）"},
  "07464_全_Z_說文‧入部": {"headline": "「全」本来指没有瑕疵的纯玉。", "original_meaning": "「全」指纯粹、完整、没有缺陷，最早用来形容纯色的玉。", "structure_desc": "「全」字从「入」从「玉」，本义是指没有瑕疵的、纯色的玉。古人认为纯色的玉最完美，所以「全」引申出「完整」「全部」「保全」的意思，比如「完全」「齐全」「两全其美」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「㒰」條（今字作「全」）；香港中文大學《漢語多功能字庫》「全」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%A8（2026-11-03 查閱）"},
  "07468_公_Z_說文‧八部": {"headline": "「公」就是和「私」对着干。", "original_meaning": "「公」指公平、公共，和「私」相对。", "structure_desc": "关于「公」字的来历，古人认为是和「私」相对的。「厶」就是「私」，画的是一个人只顾自己绕圈圈；而「公」在「厶」上面加了「八」（表示分开、相背），意思是和自私对着干，所以「公」就是公平、公共的意思。也有学者认为「公」本来是瓮（一种大肚子的陶器）的象形字，后来被借来表示公私的公。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「公」條；香港中文大學《漢語多功能字庫》「公」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%AC（2026-11-03 查閱）"},
  "07475_关_Z_小篆": {"headline": "「关」就是给门上门闩。", "original_meaning": "「关」的本义是用木棍把门闩上，后来引申为关闭、关口等意思。", "structure_desc": "金文的「关」字，外面是两扇门，里面是用来闩门的木棍和锁环，本义就是把门关上。后来引申出「关闭」「关口」「机关」「关心」等意思。繁体字写作「關」，现在简化为「关」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「關」條；香港中文大學《漢語多功能字庫》「關」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%97%9C（2026-11-03 查閱）"},
  "07478_其_Z_說文‧箕部": {"headline": "「其」本来画的是簸箕。", "original_meaning": "「其」本来指簸箕（扬米去糠的工具），后来多借用作代词。", "structure_desc": "甲骨文的「其」字，画的就是一个簸箕的形状，是「箕」的本字。后来「其」被借用作代词，表示「他的」「那个」「难道」等意思，比如「其他」「其实」。簸箕的意思则另造了「箕」字来表示。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「箕」條（今字作「其」）；香港中文大學《漢語多功能字庫》「其」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%B6（2026-11-03 查閱）"},
  "07610_出_Z_說文‧出部": {"headline": "「出」就是一只脚从山洞里迈出来。", "original_meaning": "「出」的本义是外出、从里面到外面。", "structure_desc": "甲骨文的「出」字，上面是一只脚（「止」），下面是一个洞穴（「凵」）。古人住在山洞里，所以用「脚从洞穴里走出来」来表示「外出」的意思。后来引申出「出现」「出产」「出去」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「出」條；香港中文大學《漢語多功能字庫》「出」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%87%BA（2026-11-03 查閱）"},
  "07622_分_Z_說文‧八部": {"headline": "「分」就是拿刀把东西切成两半。", "original_meaning": "「分」的本义是分开、切分。", "structure_desc": "甲骨文的「分」字，上面是「八」（表示分开的两样东西），下面是「刀」，合起来就是用刀把东西切开的意思。「分」和「八」读音相近，意思也差不多，有些学者认为它们本来是同一个字。后来「分」引申出「区分」「分配」「分数」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「分」條；香港中文大學《漢語多功能字庫》「分」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%86（2026-11-03 查閱）"},
  "07659_别_Z_小篆": {"headline": "「别」就是用刀把骨肉分开。", "original_meaning": "「别」的本义是分解、分割，后来引申为分别、离别。", "structure_desc": "甲骨文的「别」字，是一把刀和一块骨头的组合，表示用刀把骨肉分割开。本义是分解、分割。后来引申出「分别」「区别」「离别」等意思，比如「告别」「久别重逢」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𠛰」條（今字作「別」）；香港中文大學《漢語多功能字庫》「別」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%A5（2026-11-03 查閱）"},
  "07664_到_Z_說文‧至部": {"headline": "「到」就是到达、来到目的地。", "original_meaning": "「到」的本义是来到、到达。", "structure_desc": "「到」从「至」（表示到达），「刀」表音，本义是来到、到达。比如「到达」「到站」「到时候」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「到」條；香港中文大學《漢語多功能字庫》「到」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%B0（2026-11-03 查閱）"},
  "07670_制_Z_說文‧刀部": {"headline": "「制」就是用刀砍断树木。", "original_meaning": "「制」的本义是裁剪、砍断，引申为制作、规定。", "structure_desc": "金文的「制」字，是一棵树（木或未）和一把刀的组合，表示用刀斧砍劈木材。本义是裁剪、砍断。后来引申出制作、规定、制度等意思，比如「制造」「制定」「制度」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「制」條；香港中文大學《漢語多功能字庫》「制」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%B6（2026-11-03 查閱）"},
  "07693_前_Z_說文‧止部": {"headline": "「前」就是穿上鞋子往前走。", "original_meaning": "「前」的本义是前进、向前走。", "structure_desc": "金文的「前」字，上面是一只脚（止），下面是一只鞋子（舟），合起来表示穿上鞋子向前走，本义是前进。后来引申出「前面」「以前」「前进」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「歬」條（今字作「前」）；香港中文大學《漢語多功能字庫》「前」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%89%8D（2026-11-03 查閱）"},
  "07771_力_Z_說文‧力部": {"headline": "「力」画的是古代翻土的农具。", "original_meaning": "「力」指力气、力量，因为干活要用力气。", "structure_desc": "甲骨文的「力」字，画的是一种古代农具，就是一根尖头木棒，中间的短横是踏脚的地方。用农具翻土耕作需要力气，所以「力」就引申出「力气」「力量」的意思，比如「力气」「动力」「能力」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「力」條；香港中文大學《漢語多功能字庫》「力」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%9B（2026-11-03 查閱）"},
  "07776_加_Z_說文‧力部": {"headline": "「加」就是干活时加把劲。", "original_meaning": "「加」的本义是增加、加上。", "structure_desc": "金文的「加」字，左边是「力」（农具），右边是「口」。有学者认为，「力」表示用农具掘地干活，「口」表示用力时嘴里的呼喝声，合起来就是干活时加把劲的意思。后来引申出「增加」「加上」「加入」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「加」條；香港中文大學《漢語多功能字庫》「加」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%A0（2026-11-03 查閱）"},
  "07784_动_Z_小篆": {"headline": "「动」就是行动、动起来。", "original_meaning": "「动」（動）的本义是行动、起动。", "structure_desc": "「动」的繁体字是「動」，从「力」，「重」表音，本义是行动、起动。比如「运动」「动手」「感动」。现在简化为「动」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「動」條；香港中文大學《漢語多功能字庫》「動」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8B%95（2026-11-03 查閱）"},
  "07894_化_Z_說文‧𠤎部": {"headline": "「化」就是一个人正、一个人倒，颠倒就是变化。", "original_meaning": "「化」的本义是变化、改变。", "structure_desc": "甲骨文和金文的「化」字，是一正一反两个人形，用一个人朝上、一个人朝下的样子，表示颠倒、变化的意思。本义是变化。后来引申出「教化」「化学」「文化」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「化」條；香港中文大學《漢語多功能字庫》「化」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8C%96（2026-11-03 查閱）"},
  "07937_十_Z_說文‧十部": {"headline": "「十」就是数字十，一竖加一横。", "original_meaning": "「十」是数字十。", "structure_desc": "甲骨文和早期金文里，「十」写作一竖「丨」。关于这一竖的来历有很多说法：有人认为像针，用针来代表数字十；有人认为数到十就进一位，为了和「一」（横）区分，所以写成竖；还有人认为是两只手合十竖起来的样子。后来在竖画中间加了一点（后来变成一横），才写成现在的「十」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「十」條；香港中文大學《漢語多功能字庫》「十」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%81（2026-11-03 查閱）"},
  "08059_去_Z_說文‧去部": {"headline": "「去」就是离开、往别处走。", "original_meaning": "「去」的本义是离开、前往别处。", "structure_desc": "「去」字由「大」和「口」组成。关于它的来历有不同看法，一种认为「大」「口」表示张大嘴巴，是「呿」（张口）的本字。但「去」在实际使用中多表示离开、前往的意思，比如「去年」「过去」「去到」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「去」條；香港中文大學《漢語多功能字庫》「去」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8E%BB（2026-11-03 查閱）"},
  "08072_又_Z_說文‧又部": {"headline": "「又」本来画的是一只右手。", "original_meaning": "「又」的本义是右手，后来借用作「再一次」的意思。", "structure_desc": "甲骨文和金文的「又」字，画的是一只右手的侧面形状，所以本义就是右手。后来「又」被借用来表示「再一次」「还」的意思，比如「又来一个」「又高又大」。表示右手的意思则另造了「右」字。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「又」條；香港中文大學《漢語多功能字庫》「又」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%88（2026-11-03 查閱）"},
  "08081_发_Z_小篆": {"headline": "「发」就是拉开弓弦把箭射出去。", "original_meaning": "「发」（發）的本义是发射、射箭。", "structure_desc": "甲骨文的「发」字，画的是一张弓，弓弦那里有几个小点，表示箭射出去后弓弦还在颤动的样子，本义就是发射。后来引申出「发生」「发现」「发展」等意思。繁体字写作「發」，现在简化为「发」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「發」條；香港中文大學《漢語多功能字庫》「發」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%99%BC（2026-11-03 查閱）"},
  "08106_只_Z_說文‧只部": {"headline": "「只」是语气词，后来表示「仅仅」。", "original_meaning": "「只」本义是句末语气词，后来表示「仅仅」「只有」。", "structure_desc": "「只」从「口」，下面的笔画像气往下走的样子，本来是句末的语气词，相当于「啊」「呢」。后来「只」多用来表示「仅仅」「只有」的意思，比如「只此一家」「只管去做」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「只」條；香港中文大學《漢語多功能字庫》「只」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%AA（2026-11-03 查閱）"},
  "08111_可_Z_說文‧可部": {"headline": "「可」就是「行、能够」的意思。", "original_meaning": "「可」的本义是可以、能够。", "structure_desc": "「可」从「口」，「丂」表音。关于「丂」的形状，有人认为像树枝，有人认为像斧头的柄。「可」后来借用来表示「可以」「能够」的意思，比如「可以」「可爱」「许可」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「可」條；香港中文大學《漢語多功能字庫》「可」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%AF（2026-11-03 查閱）"},
  "08131_吃_Z_說文‧口部": {"headline": "「吃」本来指口吃，后来表示吃饭。", "original_meaning": "「吃」的本义是口吃（说话结巴），后来才表示吃东西。", "structure_desc": "「吃」从「口」，「气」表音，本义是口吃，就是说话不流利、结巴。后来「吃」被用来表示吃东西的意思，这个意思古代一般写作「喫」。比如「吃饭」「吃苦」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𠯏」條（今字作「吃」）；香港中文大學《漢語多功能字庫》「吃」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%83（2026-11-03 查閱）"},
  "08136_合_Z_說文‧亼部": {"headline": "「合」就是盖子和器皿扣在一起。", "original_meaning": "「合」的本义是相合、合拢，引申为聚合、会合。", "structure_desc": "甲骨文和金文的「合」字，上面是盖子，下面是器皿（口），合起来表示盖子和器皿扣在一起，本义是相合。后来引申出「会合」「聚合」「合作」等意思，比如「合力」「合二为一」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「合」條；香港中文大學《漢語多功能字庫》「合」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%88（2026-11-03 查閱）"},
  "08140_同_Z_說文‧𠔼部": {"headline": "「同」就是「一样、相同」的意思。", "original_meaning": "「同」的本义是会合、相同。", "structure_desc": "甲骨文的「同」字，有学者认为外面像桶、筒一类的器物，里面加「口」。「同」的本义是会合、相同，表示一样、没有差别。比如「同样」「相同」「共同」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「同」條；香港中文大學《漢語多功能字庫》「同」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%8C（2026-11-03 查閱）"},
  "08142_后_Z_說文‧后部": {"headline": "「后」本来指君主，后来指皇后。", "original_meaning": "「后」的本义是君主、君王。", "structure_desc": "「后」和「司」在甲骨文里其实是同一个字，只是方向相反。「后」在金文里才出现，本义是君主、君王。比如「后羿」就是古代的一位君主。后来「后」专指君王的妻子，也就是皇后、太后。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「后」條；香港中文大學《漢語多功能字庫》「后」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%8E（2026-11-03 查閱）"},
  "08268_和_Z_說文‧口部": {"headline": "「和」就是声音相应、和谐相处。", "original_meaning": "「和」的本义是声音相应、和谐，引申为和睦。", "structure_desc": "「和」从「口」，「禾」表音，本义是声音相应和，就是你唱我和、互相应答的意思。后来引申为和谐、和睦，比如「和平」「和气」「和和美美」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「和」條；香港中文大學《漢語多功能字庫》「和」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%92%8C（2026-11-03 查閱）"},
  "08862_回_Z_說文‧囗部": {"headline": "「回」就是水流旋转、打圈圈。", "original_meaning": "「回」的本义是旋转、回转。", "structure_desc": "「回」字画的是回环旋转的形状，像水流打圈圈的样子。本义是旋转、回转。后来引申出「回来」「回答」「回想」等意思，比如「回家」「回复」「回忆」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「回」條；香港中文大學《漢語多功能字庫》「回」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9B%9E（2026-11-03 查閱）"},
  "08864_因_Z_說文‧囗部": {"headline": "「因」就是人被衣服裹在里面。", "original_meaning": "「因」的本义是依靠、凭借，也表示原因。", "structure_desc": "甲骨文的「因」字，是一个人（大）被衣服包裹着的样子，本义是人在衣服里。后来「因」引申出「凭借」「沿袭」「原因」等意思，比如「因为」「原因」「因势利导」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「因」條；香港中文大學《漢語多功能字庫》「因」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9B%A0（2026-11-03 查閱）"},
  "08893_国_Z_小篆": {"headline": "「国」就是用围墙围起来的城邦。", "original_meaning": "「国」（國）的本义是国家、城邦。", "structure_desc": "金文的「国」字，外面是「囗」（表示围墙、边界），里面是「或」（表示武器和人口）。合起来就是用围墙保护起来的城邦，本义就是国家。繁体字写作「國」，现在简化为「国」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「國」條；香港中文大學《漢語多功能字庫》「國」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%8B（2026-11-03 查閱）"},
  "08936_在_Z_說文‧土部": {"headline": "「在」就是存在、待在某个地方。", "original_meaning": "「在」的本义是存在、处于某个位置。", "structure_desc": "「在」从「土」，「才」表音，本义是存在、处于某个位置。甲骨文和金文里常借用「才」字来表示「在」。后来「在」引申出「在于」「正在」等意思，比如「在家」「正在」「存在」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「在」條；香港中文大學《漢語多功能字庫》「在」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%A8（2026-11-03 查閱）"},
  "08944_地_Z_說文‧土部": {"headline": "「地」就是我们脚下的大地。", "original_meaning": "「地」指大地、土地，和「天」相对。", "structure_desc": "「地」从「土」，「也」表音，本义是大地，就是我们脚下踩着的土地，和天上的「天」相对。古人认为天是轻清的阳气上浮形成的，地是重浊的阴气下沉形成的。比如「土地」「地面」「天地」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「地」條；香港中文大學《漢語多功能字庫》「地」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%B0（2026-11-03 查閱）"},
  "09430_外_Z_說文‧夕部": {"headline": "「外」就是里面的对面。", "original_meaning": "「外」指外面、外部，和「内」相对。", "structure_desc": "古人用占卜时的裂纹来区分内外，竖画是中界，横向裂纹指向的是里面，另一面就是外面。所以甲骨文用「卜」字来表示「外」，金文又加了「月」来表音。后来「外」表示外面、外部，比如「外面」「里外」「外国」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「外」條；香港中文大學《漢語多功能字庫》「外」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%96（2026-11-03 查閱）"},
  "09434_多_Z_說文‧多部": {"headline": "「多」就是两块肉，古时候两块肉就算多了。", "original_meaning": "「多」的本义是数量多，和「少」相对。", "structure_desc": "甲骨文的「多」字，是两块肉叠在一起的样子。古时候物资匮乏，能有两块肉就算很多了，所以用两块肉来表示「多」的意思。后来「多」泛指数量大，比如「很多」「多少」「众多」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「多」條；香港中文大學《漢語多功能字庫》「多」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%9A（2026-11-03 查閱）"},
  "09447_大_Z_說文‧大部": {"headline": "「大」画的是一个张开双臂的大人。", "original_meaning": "「大」指体积、面积、数量等超过一般，和「小」相对。", "structure_desc": "甲骨文的「大」字，画的是一个人正面站立、双臂张开的样子。本义就是成年人（大人），和表示小孩的「子」相对。因为大人比小孩大，所以引申出「大小」的「大」。比如「大人」「大小」「巨大」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「大」條；香港中文大學《漢語多功能字庫》「大」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%A7（2026-11-03 查閱）"},
  "09449_天_Z_說文‧一部": {"headline": "「天」就是人头顶上的那一片空间。", "original_meaning": "「天」本义指人的头顶，后来指天空。", "structure_desc": "甲骨文的「天」字，下面是一个正面站立的人（大），上面突出头部（一个圆点或一横）。本义是人的头顶。因为头顶上方就是天空，而天空和头顶一样都是最高的地方，所以「天」就引申为天空的意思，比如「天空」「天地」「今天」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「天」條；香港中文大學《漢語多功能字庫》「天」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%A9（2026-11-03 查閱）"},
  "09460_头_Z_小篆": {"headline": "「头」就是人的脑袋。", "original_meaning": "「头」（頭）的本义是脑袋、头部。", "structure_desc": "「头」的繁体字是「頭」，从「页」（表示头部），「豆」表音。「页」字画的是一个人形，特别突出头部。「头」的本义就是人的脑袋。现在简化为「头」。比如「头发」「头顶」「开头」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「頭」條；香港中文大學《漢語多功能字庫》「頭」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A0%AD（2026-11-03 查閱）"},
  "09533_好_Z_說文‧女部": {"headline": "「好」就是妈妈抱着孩子，真好。", "original_meaning": "「好」的本义是美好，引申为优点多、令人满意。", "structure_desc": "甲骨文和金文的「好」字，左边是一个女子，右边是一个孩子，合起来表示母亲抱着孩子的情景。有学者认为这是母子相亲的样子，所以「好」的本义是美好。后来引申出「优点多」「令人满意」等意思，比如「好坏」「好人」「美好」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「好」條；香港中文大學《漢語多功能字庫》「好」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A5%BD（2026-11-03 查閱）"},
  "09538_如_Z_說文‧女部": {"headline": "「如」就是照着做、跟从。", "original_meaning": "「如」的本义是顺从、跟随，后来表示「好像」「如同」。", "structure_desc": "「如」从「女」从「口」，表示口里发出命令，女子听从照办的意思。本义是顺从、跟随。后来引申出「如同」「好像」等意思，比如「如果」「如今」「如意」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「如」條；香港中文大學《漢語多功能字庫》「如」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A6%82（2026-11-03 查閱）"},
  "10000_子_Z_說文‧子部": {"headline": "「子」画的是一个被包在襁褓里的婴儿。", "original_meaning": "「子」指小孩、婴儿，也指儿女。", "structure_desc": "甲骨文和金文的「子」字，画的是一个刚出生的婴儿，头上有头发，两条小腿包在襁褓里。本义就是小孩、婴儿。后来也用来表示儿女，或者对人的尊称，比如「孔子」「孟子」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「子」條；香港中文大學《漢語多功能字庫》「子」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%90（2026-11-03 查閱）"},
  "10022_学_Z_小篆": {"headline": "「学」就是教孩子用手摆弄算筹学算术。", "original_meaning": "「学」（學）的本义是学习、教导。", "structure_desc": "甲骨文的「学」字，画的是双手摆弄算筹（古代计数的工具）来学习算术的样子。金文又加了一个「子」（小孩），表示学习是和孩子有关的。繁体字写作「學」，现在简化为「学」。比如「学习」「学校」「学问」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「斆」條（今字作「學」）；香港中文大學《漢語多功能字庫》「學」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%B8（2026-11-03 查閱）"},
  "10074_定_Z_說文‧宀部": {"headline": "「定」就是屋里有了落脚的地方，心就安稳了。", "original_meaning": "「定」的本义是安定、安稳。", "structure_desc": "「定」从「宀」（房屋），「正」表音。房屋是安身的地方，有了房子心就安定了，所以「定」的本义是安定。后来引申出「决定」「一定」「稳定」等意思，比如「安定」「决定」「一定」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「定」條；香港中文大學《漢語多功能字庫》「定」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%9A（2026-11-03 查閱）"},
  "10078_实_Z_小篆": {"headline": "「实」就是屋子里堆满了宝贝。", "original_meaning": "「实」（實）的本义是富足、充实。", "structure_desc": "「实」的繁体字是「實」，从「宀」（房屋）从「贯」（穿成串的钱）。合起来就是屋子里堆满了钱财宝贝的意思，本义是富足、充实。后来引申出「真实」「实际」「果实」等意思，比如「诚实」「实际」「果实」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「實」條；香港中文大學《漢語多功能字庫》「實」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AF%A6（2026-11-03 查閱）"},
  "10102_家_Z_說文‧宀部": {"headline": "「家」就是屋里养着猪，就是家。", "original_meaning": "「家」指家庭、住所。", "structure_desc": "甲骨文和金文的「家」字，上面是房屋（宀），下面是一头猪（豕）。古人家里养猪，所以用「屋里有猪」来表示家。本义就是家庭、住所。后来引申出「家族」「家里」等意思，比如「家人」「家庭」「国家」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「家」條；香港中文大學《漢語多功能字庫》「家」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%B6（2026-11-03 查閱）"},
  "10169_对_Z_小篆": {"headline": "「对」本来是开荒立界，后来表示应答、相对。", "original_meaning": "「对」（對）的本义是开辟土地、树立地界，后来表示应答、相对。", "structure_desc": "「对」的繁体字是「對」。古人开荒后要树立地界，地界多半用植树来标记，所以「对」的本义是开辟土地、立下地界。后来「对」被借用来表示应答、相对的意思，比如「回答」「对手」「对错」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𡭊」條（今字作「對」）；香港中文大學《漢語多功能字庫》「對」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%8D（2026-11-03 查閱）"},
  "10191_小_Z_說文‧小部": {"headline": "「小」就是用几个小点点表示细小。", "original_meaning": "「小」指体积、面积、数量等不大，和「大」相对。", "structure_desc": "关于「小」字的来历有两种说法：一种认为用三个小点来表示事物很微小；另一种认为「小」是「沙」的本字，用细小的沙粒来表示微小。不管哪种说法，「小」的本义就是微小、不大，比如「小孩」「小心」「大小」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「小」條；香港中文大學《漢語多功能字庫》「小」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%8F（2026-11-03 查閱）"},
  "10225_就_Z_說文‧京部": {"headline": "「就」就是到高处去祭祀。", "original_meaning": "「就」的本义是到高处去、靠近，引申为成就、完成。", "structure_desc": "甲骨文和金文的「就」字，上面是宗庙建筑，下面是高台，合起来表示到高台上祭祀的意思。本义是靠近、去到某处。后来引申出「成就」「完成」「就是」等意思，比如「成就」「就是」「就业」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「就」條；香港中文大學《漢語多功能字庫》「就」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%B1（2026-11-03 查閱）"},
  "10261_展_Z_說文‧尸部": {"headline": "「展」就是人躺在床上翻来覆去。", "original_meaning": "「展」的本义是辗转、转动，引申为展开、舒展。", "structure_desc": "「展」从「尸」（表示人），本义是人躺在床上翻来覆去。因为人躺着的时候四肢会舒展开，所以「展」引申出「展开」「舒展」「展示」等意思，比如「展开」「展览」「发展」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「展」條；香港中文大學《漢語多功能字庫》「展」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B1%95（2026-11-03 查閱）"},
  "10661_工_Z_說文‧工部": {"headline": "「工」画的是古代的曲尺和工具。", "original_meaning": "「工」的本义是工匠、工具，引申为精巧、工作。", "structure_desc": "甲骨文和金文的「工」字，画的是一种工具，上面像曲尺（用来画直角的工具），下面像斧刃。本义就是工匠用的工具。后来引申出「工匠」「工作」「精巧」等意思，比如「工人」「工作」「工巧」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「工」條；香港中文大學《漢語多功能字庫》「工」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%A5（2026-11-03 查閱）"},
  "10673_己_Z_說文‧己部": {"headline": "「己」本来画的是捆东西的绳子。", "original_meaning": "「己」本来指用来捆绑的绳子，后来表示自己。", "structure_desc": "甲骨文和金文的「己」字，画的是一根弯弯曲曲的绳子，本义是用来捆绑东西的绳子，是「纪」的本字。后来「己」被借用来表示「自己」「自身」的意思，也用作天干第六位。比如「自己」「知己」「舍己为人」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「己」條；香港中文大學《漢語多功能字庫》「己」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%B1（2026-11-03 查閱）"},
  "10674_已_Z_小篆": {"headline": "「已」本来和「巳」是同一个字。", "original_meaning": "「已」表示停止、完毕，也作虚词。", "structure_desc": "古文字里「已」和「巳」原本是同一个字，后来才分开。「已」多用作虚词，表示「停止」「完毕」「已经」等意思，比如「已经」「而已」「不能自已」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「巳」條（今字作「已」）；香港中文大學《漢語多功能字庫》「已」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%B2（2026-11-03 查閱）"},
  "10690_市_Z_說文‧冂部": {"headline": "「市」就是吵吵闹闹的集市。", "original_meaning": "「市」指集市、市场，就是做买卖的地方。", "structure_desc": "甲骨文和金文的「市」字，有学者认为其中的「兮」表示喧闹的声音，合起来表示市场里吵吵闹闹做买卖的情景。本义就是集市、市场。后来引申出「城市」「买」等意思，比如「市场」「城市」「市恩」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「市」條；香港中文大學《漢語多功能字庫》「市」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%82（2026-11-03 查閱）"},
  "10803_平_Z_說文‧于部": {"headline": "「平」就是呼吸平稳、不颠簸。", "original_meaning": "「平」的本义是平稳、不倾斜。", "structure_desc": "「平」字上面是表示呼气的部分，下面一横表示平稳的状态。本义是气平稳、不颠簸。后来引申出「平坦」「公平」「和平」等意思，比如「平地」「公平」「平安」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「平」條；香港中文大學《漢語多功能字庫》「平」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B9%B3（2026-11-03 查閱）"},
  "10804_年_Z_說文‧禾部": {"headline": "「年」就是人背着收割的庄稼，丰收了就是一年。", "original_meaning": "「年」的本义是谷物成熟、丰收。", "structure_desc": "甲骨文的「年」字，画的是一个人背着一捆收割好的庄稼，表示谷物成熟丰收的意思。古时候人们以谷物成熟一次为一年，所以「年」就有了年岁的意思。比如「今年」「过年」「年年有余」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「年」條；香港中文大學《漢語多功能字庫》「年」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B9%B4（2026-11-03 查閱）"},
  "10836_应_Z_小篆": {"headline": "「应」就是心里觉得该做的事。", "original_meaning": "「应」（應）的本义是应当、应该。", "structure_desc": "「应」的繁体字是「應」，从「心」，表示心里的判断。本义是应当、应该，就是心里觉得该怎么做。后来也表示应答、回应，比如「应该」「答应」「反应」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「應」條；香港中文大學《漢語多功能字庫》「應」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%87%89（2026-11-03 查閱）"},
  "10854_度_Z_說文‧又部": {"headline": "「度」就是用手来量长短。", "original_meaning": "「度」的本义是量长短的标准，引申为制度、程度。", "structure_desc": "「度」从「又」（手），表示用手来量度长短。本义是计量长短的标准。后来引申出「制度」「程度」「气度」等意思，比如「尺度」「制度」「态度」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「度」條；香港中文大學《漢語多功能字庫》「度」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BA%A6（2026-11-03 查閱）"},
  "10938_建_Z_說文‧廴部": {"headline": "「建」就是用手把柱子立起来。", "original_meaning": "「建」的本义是树立、建立。", "structure_desc": "甲骨文和金文的「建」字，是一只手拿着一根木柱，把它竖立起来的样子。本义是树立、建立。后来引申出「建设」「建造」「建议」等意思，比如「建立」「建设」「建言」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「建」條；香港中文大學《漢語多功能字庫》「建」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BB%BA（2026-11-03 查閱）"},
  "10944_开_Z_小篆": {"headline": "「开」就是用两只手把门闩拿掉。", "original_meaning": "「开」（開）的本义是开门、打开。", "structure_desc": "「开」的繁体字是「開」，金文的字形是两只手把门上的横木（门闩）拿掉，把门打开的样子。本义是开门、打开。后来引申出「开始」「开放」「开发」等意思，比如「开门」「开始」「开心」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「開」條；香港中文大學《漢語多功能字庫》「開」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%96%8B（2026-11-03 查閱）"},
  "11027_当_Z_小篆": {"headline": "「当」就是两块田地对等、相当。", "original_meaning": "「当」（當）的本义是相对、相当。", "structure_desc": "「当」的繁体字是「當」，从「田」，「尚」表音。本义是两块田地相对、面积相当。后来引申出「应当」「对着」「担任」等意思，比如「应当」「当面」「担当」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「當」條；香港中文大學《漢語多功能字庫》「當」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%95%B6（2026-11-03 查閱）"},
  "11080_很_Z_說文‧彳部": {"headline": "「很」本来是不听劝、对着干。", "original_meaning": "「很」的本义是违逆、不听从，后来表示程度深。", "structure_desc": "「很」从「彳」（表示行走），「艮」表音。本义是违逆、不听从，就是别人说什么都不听，对着干。后来「很」被借用来表示程度深，相当于「非常」，比如「很好」「很快」「很多」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「很」條；香港中文大學《漢語多功能字庫》「很」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%88（2026-11-03 查閱）"},
  "11095_得_Z_說文‧彳部": {"headline": "「得」就是在路上捡到宝贝。", "original_meaning": "「得」的本义是得到、获得。", "structure_desc": "甲骨文和金文的「得」字，是一只手拿着贝（古代的钱币），有的还加了表示道路的「彳」，合起来表示在路上捡到了宝贝。本义是得到、获得。后来引申出「得到」「得失」「得意」等意思。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「得」條；香港中文大學《漢語多功能字庫》「得」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%97（2026-11-03 查閱）"},
  "11139_心_Z_說文‧心部": {"headline": "「心」画的就是人的心脏。", "original_meaning": "「心」指人的心脏，也指思想、情感。", "structure_desc": "甲骨文和金文的「心」字，画的就是人的心脏的形状，外面是心包，里面是心房心室。古人认为心是管思想的，所以「心」也指心思、情感，比如「心情」「心思」「用心」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「心」條；香港中文大學《漢語多功能字庫》「心」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%83（2026-11-03 查閱）"},
  "11179_快_Z_說文‧心部": {"headline": "「快」就是心里高兴、美滋滋。", "original_meaning": "「快」的本义是喜悦、高兴，后来表示速度快。", "structure_desc": "「快」从「心」，「夬」表音。本义是心里高兴、畅快。后来「快」引申出「速度快」的意思，因为心里畅快的时候做事也会特别带劲。比如「快乐」「快速」「快点」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「快」條；香港中文大學《漢語多功能字庫》「快」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%AB（2026-11-03 查閱）"},
  "11239_性_Z_說文‧心部": {"headline": "「性」就是人天生的本性。", "original_meaning": "「性」的本义是天性、本性。", "structure_desc": "「性」从「心」，「生」表音。本义是人的天性、本性，就是人生下来就有的特质。古人认为人天生有善良的本性。后来「性」也指事物的性质、特点，比如「本性」「性格」「性质」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「性」條；香港中文大學《漢語多功能字庫》「性」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%A7（2026-11-03 查閱）"},
  "11397_情_Z_說文‧心部": {"headline": "「情」就是人心里的喜怒哀乐。", "original_meaning": "「情」的本义是感情、情绪。", "structure_desc": "「情」从「心」，「青」表音。本义是人的感情、情绪，就是人心里产生的喜怒哀乐。古人说，本性的好坏、喜怒、哀乐就叫做情。比如「感情」「心情」「爱情」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「情」條；香港中文大學《漢語多功能字庫》「情」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%83%85（2026-11-03 查閱）"},
  "11443_想_Z_說文‧心部": {"headline": "「想」就是在心里动脑筋琢磨。", "original_meaning": "「想」的本义是思考、思索。", "structure_desc": "「想」从「心」，「相」表音。本义是在心里思考、琢磨。后来引申出「希望」「想念」等意思，比如「想法」「想念」「理想」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「想」條；香港中文大學《漢語多功能字庫》「想」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%83%B3（2026-11-03 查閱）"},
  "11471_意_Z_說文‧心部": {"headline": "「意」就是话里透出来的心思。", "original_meaning": "「意」的本义是心思、意思。", "structure_desc": "「意」从「心」从「音」，表示从声音或言语里看出来的心思。本义是心意、意思。后来引申出「意愿」「意料」「意思」等意思，比如「意思」「心意」「意料」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「意」條；香港中文大學《漢語多功能字庫》「意」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%84%8F（2026-11-03 查閱）"},
  "11728_成_Z_說文‧戊部": {"headline": "「成」就是拿着武器守住城池。", "original_meaning": "「成」的本义是完成、成功。", "structure_desc": "甲骨文的「成」字，是一把斧头（戌）和一座城邑（囗）的组合，表示用武器守卫城池。有学者认为「成」本来是「城」的本字。后来「成」引申出「完成」「成功」「成就」等意思，比如「成功」「完成」「成就」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「成」條；香港中文大學《漢語多功能字庫》「成」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%90（2026-11-03 查閱）"},
  "11729_我_Z_說文‧我部": {"headline": "「我」本来是一把带锯齿的兵器。", "original_meaning": "「我」本来是一种兵器，后来借来表示自己。", "structure_desc": "甲骨文和金文的「我」字，画的是一把带锯齿的长柄兵器，本义是一种类似锯的武器。后来被借用作第一人称代词，表示自己。比如「我们」「自我」「我行我素」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「我」條；香港中文大學《漢語多功能字庫》「我」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%91（2026-11-03 查閱）"},
  "11776_所_Z_說文‧斤部": {"headline": "「所」就是拿着斧头守在门口。", "original_meaning": "「所」的本义是处所、地方。", "structure_desc": "「所」从「户」（一扇门）从「斤」（斧头），有学者认为是拿着斧头守在门口的意思。本义是处所、地方。后来「所」虚化为助词，用在动词前面，比如「所以」「所有」「无所不在」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「所」條；香港中文大學《漢語多功能字庫》「所」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%80（2026-11-03 查閱）"},
  "11787_手_Z_說文‧手部": {"headline": "「手」画的是有五根手指的手掌。", "original_meaning": "「手」就是人的手。", "structure_desc": "甲骨文里「手」一般写作「又」，只画了三根手指。后来「又」被借用作连词，人们就另造了「手」字。金文的「手」字画了五根手指，连着手腕。「手」是汉字里最重要的部件之一，很多和动作有关的字都带「手」字旁。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「手」條；香港中文大學《漢語多功能字庫》「手」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%8B（2026-11-03 查閱）"},
  "11850_把_Z_說文‧手部": {"headline": "「把」就是用手抓住东西。", "original_meaning": "「把」的本义是握持、抓住。", "structure_desc": "「把」从「手」，「巴」表音。本义是用手握住、抓住。后来引申出量词用法（一把刀）和介词用法（把门打开）等。比如「把握」「把门」「一把刀」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「把」條；香港中文大學《漢語多功能字庫》「把」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8A%8A（2026-11-03 查閱）"},
  "12176_提_Z_說文‧手部": {"headline": "「提」就是用手把东西拎起来。", "original_meaning": "「提」的本义是悬持、拎起。", "structure_desc": "「提」从「手」，「是」表音。本义是用手把东西拎起来、悬空拿着。后来引申出「提起」「提出」「提醒」等意思，比如「提水」「提问」「提升」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「提」條；香港中文大學《漢語多功能字庫》「提」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8F%90（2026-11-03 查閱）"},
  "12543_政_Z_說文‧攴部": {"headline": "「政」就是拿着棍棒去打仗。", "original_meaning": "「政」的本义是征伐，后来表示政治。", "structure_desc": "「政」从「攴」（手持棍棒），「正」表音。「正」是「征」的本字，表示脚朝着目标前进。合起来就是拿着棍棒去征伐的意思。后来「政」引申出「政治」「政务」等意思，比如「政治」「政府」「政策」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「政」條；香港中文大學《漢語多功能字庫》「政」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%94%BF（2026-11-03 查閱）"},
  "12569_教_Z_說文‧教部": {"headline": "「教」就是拿着教鞭教孩子算数。", "original_meaning": "「教」的本义是教导、教育。", "structure_desc": "甲骨文的「教」字，左边是一个孩子（子），右边是一只手拿着教鞭（攴），中间是算筹（爻）。合起来就是老师拿着教鞭，教孩子摆弄算筹学算术的样子。本义就是教导。古人说「教学相长」，就是教和学互相促进。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「敎」條（今字作「教」）；香港中文大學《漢語多功能字庫》「教」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%99（2026-11-03 查閱）"},
  "12615_文_Z_說文‧文部": {"headline": "「文」就是人身上画的花纹。", "original_meaning": "「文」的本义是纹身、花纹，后来指文字。", "structure_desc": "甲骨文和金文的「文」字，画的是一个站立的人，胸前画着花纹。本义是纹身、花纹。后来人们用花纹来记录事情，「文」就有了文字的意思。比如「文字」「文章」「文化」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「文」條；香港中文大學《漢語多功能字庫》「文」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%87（2026-11-03 查閱）"},
  "12656_新_Z_說文‧斤部": {"headline": "「新」就是用斧头砍木头取柴。", "original_meaning": "「新」的本义是砍柴，引申为新旧的新。", "structure_desc": "「新」从「斤」（斧头）从「木」，表示用斧头砍木头取柴。因为刚砍下来的柴火是新鲜的，所以「新」引申出「新旧」的「新」。比如「新鲜」「新年」「创新」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「新」條；香港中文大學《漢語多功能字庫》「新」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%B0（2026-11-03 查閱）"},
  "12665_方_Z_說文‧方部": {"headline": "「方」就是用一横指出刀的锋芒。", "original_meaning": "「方」的本义是刀的锋芒，后来表示方形、方向。", "structure_desc": "甲骨文和金文的「方」字，是一把刀，加一横指出刀的锋芒。本义是刀的锋芒。因为表示方形的「□」容易和别的字混，古人就借用「方」来表示方形、方向。比如「方向」「方面」「方法」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「方」條；香港中文大學《漢語多功能字庫》「方」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%B9（2026-11-03 查閱）"},
  "12704_无_Z_說文‧亡部": {"headline": "「无」画的是人拿着牛尾跳舞。", "original_meaning": "「无」的本义是跳舞，后来借来表示没有。", "structure_desc": "甲骨文的「无」字，画的是一个人手里拿着牛尾一类的饰物在跳舞。后来这个字被借用来表示「有没有」的「无」，就不再表示跳舞了。比如「无穷」「无限」「无中生有」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𣞤」條（今字作「無」）；香港中文大學《漢語多功能字庫》「無」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%84%A1（2026-11-03 查閱）"},
  "12709_日_Z_說文‧日部": {"headline": "「日」画的就是太阳。", "original_meaning": "「日」的本义是太阳，也指一天。", "structure_desc": "「日」是个象形字，画的是太阳的样子。最早是圆形的，因为圆形在甲骨上不好刻，就变成了方形。中间加一点，避免和表示框框的「囗」混淆。「日」是汉字里最重要的部件之一，很多和时间、光明有关的字都带「日」字旁。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「日」條；香港中文大學《漢語多功能字庫》「日」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%97%A5（2026-11-03 查閱）"},
  "12726_时_Z_小篆": {"headline": "「时」就是跟着太阳走的时间。", "original_meaning": "「时」的本义是时间、时节。", "structure_desc": "「时」的繁体是「時」，从「日」（太阳），「寺」表音。古人看太阳的位置来判断时间，所以「时」从「日」。本义是时间、时节。比如「时间」「时候」「四时」（春夏秋冬）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「時」條；香港中文大學《漢語多功能字庫》「時」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%99%82（2026-11-03 查閱）"},
  "12750_明_Z_說文‧明部": {"headline": "「明」就是太阳和月亮都在发光。", "original_meaning": "「明」的本义是明亮、光明。", "structure_desc": "甲骨文的「明」字，一边是「日」（太阳），一边是「月」（月亮），合起来表示日月交辉、非常明亮的意思。也有一种写法是月光透过窗户照进屋里。本义是明亮。后来引申出「明白」「聪明」等意思，比如「光明」「明白」「聪明」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「朙」條（今字作「明」）；香港中文大學《漢語多功能字庫》「明」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%8E（2026-11-03 查閱）"},
  "12783_是_Z_說文‧是部": {"headline": "「是」就是对着太阳站得正。", "original_meaning": "「是」的本义是正直、正确，后来表示判断。", "structure_desc": "「是」从「日」（太阳）从「正」（端正），表示对着太阳站得端正。本义是正直、正确。后来「是」被用作判断词，相当于「就是」的意思。比如「是非」「是的」「可是」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「是」條；香港中文大學《漢語多功能字庫》「是」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%AF（2026-11-03 查閱）"},
  "12992_最_Z_說文‧冃部": {"headline": "「最」就是冒犯着去夺取。", "original_meaning": "「最」的本义是冒犯而取，引申为极、顶。", "structure_desc": "「最」从「冃」（帽子，引申为冒犯）从「取」，表示冒着风险去夺取。后来「最」虚化为副词，表示程度达到顶点，相当于「极」「顶」。比如「最好」「最大」「最终」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「最」條；香港中文大學《漢語多功能字庫》「最」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%80（2026-11-03 查閱）"},
  "13000_月_Z_說文‧月部": {"headline": "「月」画的是弯弯的月牙。", "original_meaning": "「月」的本义是月亮，也指月份。", "structure_desc": "「月」是个象形字，画的是弯弯的月亮（半月形）。因为月亮有圆缺变化的周期，古人就用「月」来记时间，一个月就是月亮圆缺一次。「月」也是汉字里重要的部件，很多和身体有关的字都带「月」字旁（其实是「肉」字旁的变形）。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「月」條；香港中文大學《漢語多功能字庫》「月」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%88（2026-11-03 查閱）"},
  "13001_有_Z_說文‧有部": {"headline": "「有」就是手里拿着一块肉。", "original_meaning": "「有」的本义是持有、拥有。", "structure_desc": "金文的「有」字，上面是「又」（手），下面是「肉」，合起来就是手里拿着一块肉。古时候肉很珍贵，手里有肉就表示拥有东西。后来「有」就成了「没有」的反义词。比如「拥有」「富有」「有备无患」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「有」條；香港中文大學《漢語多功能字庫》「有」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%89（2026-11-03 查閱）"},
  "13036_本_Z_說文‧木部": {"headline": "「本」就是树木的根部。", "original_meaning": "「本」的本义是草木的根，引申为根本。", "structure_desc": "「本」在「木」字的下方加一横，指出树木的根部所在。本义是草木的根。因为根是树木生长的基础，所以「本」引申出「根本」「本来」等意思。比如「根本」「本来」「忘本」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「本」條；香港中文大學《漢語多功能字庫》「本」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%AC（2026-11-03 查閱）"},
  "13050_机_Z_說文‧木部": {"headline": "「机」就是弩上发箭的机关。", "original_meaning": "「机」的本义是弩机，引申为机关、机会。", "structure_desc": "「机」的繁体是「機」，从「木」，「几」表音。本义是弩机，就是古代弩上用来发射箭的装置。因为弩机是整个弩最关键的部分，一触动就会发射，所以「机」引申出「机关」「机会」「机器」等意思。比如「机会」「机器」「时机」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「機」條；香港中文大學《漢語多功能字庫》「機」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A9%9F（2026-11-03 查閱）"},
  "13093_来_Z_小篆": {"headline": "「来」本来是一棵麦子。", "original_meaning": "「来」的本义是麦子，后来借来表示到来。", "structure_desc": "甲骨文的「来」字画的是一棵麦子：中间是直直的麦穗，两边叶子下垂，下面是茎和根。本来「来」就是麦子的意思，后来被借用来表示「到来」的「来」，用久了就不还了，人们就另造了「麦」字表示麦子。比如「来到」「回来」「未来」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「來」條；香港中文大學《漢語多功能字庫》「來」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BE%86（2026-11-03 查閱）"},
  "13303_样_Z_小篆": {"headline": "「样」本来是橡树的果实。", "original_meaning": "「样」的本义是栎树的果实，后来表示样式。", "structure_desc": "「样」的繁体是「樣」，从「木」，「羕」表音。本义是栎树（橡树）的果实。后来人们用「橡」字来表示橡树的果实，「样」就专门用来表示「样式」「样子」的意思了。比如「样子」「样品」「榜样」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「樣」條；香港中文大學《漢語多功能字庫》「樣」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A8%A3（2026-11-03 查閱）"},
  "14049_次_Z_說文‧欠部": {"headline": "「次」就是人说话时溅出的口水。", "original_meaning": "「次」的本义是商议、咨询，后来表示次序、第二。", "structure_desc": "金文的「次」字，左边是「欠」（一个张着嘴的人），旁边两点像说话时溅出的口水。本义是商议、咨询（是「咨」的本字）。后来「次」引申出「次序」「第二」等意思，比如「名次」「其次」「次日」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「次」條；香港中文大學《漢語多功能字庫》「次」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AC%A1（2026-11-03 查閱）"},
  "14115_正_Z_說文‧正部": {"headline": "「正」就是脚朝着目标前进。", "original_meaning": "「正」的本义是远行，引申为端正、正确。", "structure_desc": "甲骨文和金文的「正」字，上面是「止」（脚），下面是「丁」（表示目标或城邑），合起来就是脚朝着目标前进的意思。「正」是「征」的本字。后来「正」引申出「端正」「正确」等意思，比如「正好」「正确」「正直」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「正」條；香港中文大學《漢語多功能字庫》「正」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%A3（2026-11-03 查閱）"},
  "14228_比_Z_說文‧比部": {"headline": "「比」就是两个人并排站着。", "original_meaning": "「比」的本义是并列、挨着，引申为比较。", "structure_desc": "甲骨文和金文的「比」字，画的是两个人并排站着，挨得很近。本义是并列、挨着。因为两个人挨在一起就容易比较，所以「比」引申出「比较」「比方」等意思。比如「比较」「对比」「比如」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「比」條；香港中文大學《漢語多功能字庫》「比」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AF%94（2026-11-03 查閱）"},
  "14289_民_Z_說文‧民部": {"headline": "「民」就是被刺瞎眼睛的奴隶。", "original_meaning": "「民」的本义是奴隶，后来指老百姓。", "structure_desc": "甲骨文和金文的「民」字，左边是「目」（眼睛），右边像一把利器刺向眼睛。本义是奴隶，因为古代奴隶主会刺瞎奴隶的眼睛来防止他们逃跑。后来「民」引申为普通百姓的意思，比如「人民」「民众」「民生」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「民」條；香港中文大學《漢語多功能字庫》「民」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B0%91（2026-11-03 查閱）"},
  "14324_水_Z_說文‧水部": {"headline": "「水」画的是流动的水流。", "original_meaning": "「水」就是水，也作偏旁。", "structure_desc": "「水」是个象形字，中间一竖表示水流，两边的点表示水滴。本义就是水。「水」是汉字里最重要的部件之一，很多和液体、河流有关的字都带「水」字旁（三点水）。比如「江河」「海洋」「喝水」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「水」條；香港中文大學《漢語多功能字庫》「水」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B0%B4（2026-11-03 查閱）"},
  "14433_没_Z_說文‧水部": {"headline": "「没」就是沉入水中看不见了。", "original_meaning": "「没」的本义是沉没，引申为没有。", "structure_desc": "「没」的繁体是「沒」，从「水」，右边表示沉入。本义是沉入水中。东西沉入水里就看不见了，所以「没」引申出「没有」的意思。比如「淹没」「没有」「没落」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「沒」條；香港中文大學《漢語多功能字庫》「沒」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B2%92（2026-11-03 查閱）"},
  "14485_法_Z_說文‧廌部": {"headline": "「法」就是像水一样公平的审判。", "original_meaning": "「法」的本义是法律、刑罚。", "structure_desc": "「法」的古字写作「灋」，从「水」（表示公平如水）从「廌」（一种神兽，会用角去顶无理的一方）从「去」（去除不公）。合起来就是审判要像水一样公平，让神兽去除无理的人。后来简化成「法」。比如「法律」「方法」「效法」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「灋」條（今字作「法」）；香港中文大學《漢語多功能字庫》「法」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B3%95（2026-11-03 查閱）"},
  "15481_点_Z_小篆": {"headline": "「点」就是一个小黑斑。", "original_meaning": "「点」的本义是细小的黑色斑痕。", "structure_desc": "「点」的繁体是「點」，从「黑」，「占」表音。本义是细小的黑色斑痕。后来「点」引申出很多意思，比如「点心」「点滴」「点燃」「标点」等。比如「雨点」「点头」「点灯」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「點」條；香港中文大學《漢語多功能字庫》「點」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%BB%9E（2026-11-03 查閱）"},
  "15606_然_Z_說文‧火部": {"headline": "「然」就是在火上烤狗肉。", "original_meaning": "「然」的本义是燃烧，后来作虚词。", "structure_desc": "「然」上面是「肰」（狗肉），下面是「火」，合起来就是在火上烤狗肉的意思。本义是燃烧。后来「然」被借用作虚词（表示「这样」「然而」等），人们就另造了「燃」字表示燃烧。比如「然后」「然而」「自然」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「然」條；香港中文大學《漢語多功能字庫》「然」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%84%B6（2026-11-03 查閱）"},
  "16326_理_Z_說文‧玉部": {"headline": "「理」就是顺着玉的纹路来雕琢。", "original_meaning": "「理」的本义是治玉、雕琢玉石。", "structure_desc": "「理」从「玉」，「里」表音。本义是顺着玉的纹理来雕琢玉石。因为雕琢玉石要顺着纹路，所以「理」引申出「道理」「治理」「整理」等意思。比如「道理」「治理」「整理」「理由」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「理」條；香港中文大學《漢語多功能字庫》「理」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%90%86（2026-11-03 查閱）"},
  "16607_生_Z_說文‧生部": {"headline": "「生」就是一棵草从泥土里长出来。", "original_meaning": "「生」的本义是生长、出生。", "structure_desc": "甲骨文的「生」字，下面一横是土地，上面是一棵小草（屮）从土里钻出来。本义是生长、出生。后来引申出「生命」「生活」「产生」等意思。比如「生长」「生命」「生产」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「生」條；香港中文大學《漢語多功能字庫》「生」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%9F（2026-11-03 查閱）"},
  "16616_用_Z_說文‧用部": {"headline": "「用」本来是一只木桶。", "original_meaning": "「用」的本义是木桶，后来表示使用。", "structure_desc": "甲骨文的「用」字画的是一只木桶，左边是桶身，右边是把手。本义是木桶。后来「用」被借用来表示「使用」「施行」的意思，用久了就不还了。比如「使用」「作用」「有用」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「用」條；香港中文大學《漢語多功能字庫》「用」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%A8（2026-11-03 查閱）"},
  "16964_的_Z_小篆": {"headline": "「的」就是太阳照得很明亮。", "original_meaning": "「的」的本义是明亮，后来作助词。", "structure_desc": "「的」本作「旳」，从「日」（太阳），「勺」表音。本义是明亮。后来「的」被借用作助词，用在定语和中心语之间，比如「我的书」「红色的花」。这是现代汉语里用得最多的字之一。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「旳」條（今字作「的」）；香港中文大學《漢語多功能字庫》「的」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9A%84（2026-11-03 查閱）"},
  "17099_看_Z_說文‧目部": {"headline": "「看」就是把手搭在眼睛上远望。", "original_meaning": "「看」的本义是用眼睛看东西。", "structure_desc": "「看」从「手」从「目」，像一个人把手搭在眼睛上面，遮住阳光往远处看的样子。本义就是用眼睛看东西。比如「看见」「看书」「看病」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「看」條；香港中文大學《漢語多功能字庫》「看」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%8B（2026-11-03 查閱）"},
  "17119_真_Z_說文‧𠤎部": {"headline": "「真」就是货真价实的贝币。", "original_meaning": "「真」的本义是真实、不虚假。", "structure_desc": "金文的「真」字从「贝」（古代用贝做货币），「𠂈」表音。贝是真正的钱，所以「真」有真实的意思。《说文解字》认为「真」是仙人登天的样子，但学者多认为本义和「贝」有关。后来「真」表示「真实」「真正」，和「假」相对。比如「真实」「真正」「真心」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「眞」條（今字作「真」）；香港中文大學《漢語多功能字庫》「真」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%9F（2026-11-03 查閱）"},
  "17152_着_Z_小篆": {"headline": "「着」就是明显地露出来。", "original_meaning": "「着」的本义是明显、显著。", "structure_desc": "「着」本作「著」，从「艸」（草），「者」表音。本义是明显、显著。后来「着」分化出来，表示「附着」「穿着」「着落」等意思，也作动态助词，比如「看着」「走着」。比如「穿着」「着急」「看着」。", "source": "香港中文大學《漢語多功能字庫》「著」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%91%97（2026-11-03 查閱）"},
  "17317_知_Z_說文‧矢部": {"headline": "「知」就是说话像箭一样快准。", "original_meaning": "「知」的本义是知道、懂得。", "structure_desc": "「知」从「矢」（箭）从「口」，表示说话像箭一样又快又准，一矢中的。本义是知道、懂得。因为知道了才能说得准、说得快。比如「知道」「知识」「通知」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「知」條；香港中文大學《漢語多功能字庫》「知」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9F%A5（2026-11-03 查閱）"},
  "17662_社_Z_說文‧示部": {"headline": "「社」就是祭祀土地神的地方。", "original_meaning": "「社」的本义是土地之神，也指祭祀土地神的地方。", "structure_desc": "「社」从「示」（表示祭祀）从「土」（土地），合起来就是祭祀土地神的意思。古人相信土地神能保佑庄稼丰收，所以会立社祭祀。后来「社」引申出「社会」「社团」等意思。比如「社会」「社团」「报社」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「社」條；香港中文大學《漢語多功能字庫》「社」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A4%BE（2026-11-03 查閱）"},
  "17805_种_Z_小篆": {"headline": "「种」就是禾苗的种子。", "original_meaning": "「种」的本义是植物的种子，也指种植。", "structure_desc": "「种」的繁体是「種」，从「禾」（禾苗），「重」表音。本义是植物的种子。因为种子可以种下去长出新的植物，所以「种」也表示「种植」的意思。比如「种子」「种地」「种类」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「種」條；香港中文大學《漢語多功能字庫》「種」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A8%AE（2026-11-03 查閱）"},
  "18185_等_Z_說文‧竹部": {"headline": "「等」就是把竹简整理得整整齐齐。", "original_meaning": "「等」的本义是整齐竹简，引申为等级、等同。", "structure_desc": "「等」从「竹」（竹简）从「寺」（古代的官府），表示在官府里把竹简整理得整整齐齐。本义是整齐、等同。因为竹简是按顺序排列的，所以「等」引申出「等级」「等待」等意思。比如「等级」「等待」「等于」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「等」條；香港中文大學《漢語多功能字庫》「等」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AD%89（2026-11-03 查閱）"},
  "18247_箇_Z_說文‧竹部": {"headline": "「箇」就是一根竹枝。", "original_meaning": "「箇」的本义是竹枝，后来作量词。", "structure_desc": "「箇」从「竹」，「固」表音。本义是竹枝。后来「箇」被借用作量词，相当于「个」。现在简化字写作「个」。比如「一个人」「两个苹果」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「箇」條；香港中文大學《漢語多功能字庫》「箇」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AE%87（2026-11-03 查閱）"},
  "19087_经_Z_小篆": {"headline": "「经」就是织布机上的竖线。", "original_meaning": "「经」的本义是织布的经线，引申为经过、经典。", "structure_desc": "「经」的繁体是「經」，从「糸」（丝线），「巠」表音。「巠」像织布机上纵向的经线，和横向的纬线相对。本义是织布的经线。因为经线是贯穿整匹布的主线，所以「经」引申出「经过」「经历」「经典」等意思。比如「经过」「经历」「经典」「经常」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「經」條；香港中文大學《漢語多功能字庫》「經」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B6%93（2026-11-03 查閱）"},
  "19091_结_Z_小篆": {"headline": "「结」就是把绳子系在一起。", "original_meaning": "「结」的本义是打结、系结。", "structure_desc": "「结」的繁体是「結」，从「糸」（丝线），「吉」表音。本义是把绳子系在一起、打结。后来「结」引申出「结合」「结果」「结束」等意思。比如「打结」「结合」「结果」「结束」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「結」條；香港中文大學《漢語多功能字庫》「結」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B5%90（2026-11-03 查閱）"},
  "19097_给_Z_小篆": {"headline": "「给」就是丝线充足、丰衣足食。", "original_meaning": "「给」的本义是丰足、充裕，引申为给予。", "structure_desc": "「给」的繁体是「給」，从「糸」（丝线），「合」表音。本义是丰足、充裕。丝线充足就不愁穿，所以「给」有丰足的意思。后来「给」引申出「给予」「供给」等意思。比如「给予」「供给」「给以」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「給」條；香港中文大學《漢語多功能字庫》「給」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B5%A6（2026-11-03 查閱）"},
  "19278_美_Z_說文‧羊部": {"headline": "「美」就是人头上戴着漂亮的角饰。", "original_meaning": "「美」的本义是漂亮、好看。", "structure_desc": "甲骨文的「美」字，下面是「大」（一个人），上面像头上戴着羽毛或羊角之类的装饰物。本义是漂亮、好看。古人喜欢把动物的角戴在头上做装饰，觉得这样很美。比如「美丽」「美好」「美味」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「美」條；香港中文大學《漢語多功能字庫》「美」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BE%8E（2026-11-03 查閱）"},
  "19393_老_Z_說文‧老部": {"headline": "「老」就是驼背长发、拄着拐杖的老人。", "original_meaning": "「老」的本义是年老、老人。", "structure_desc": "甲骨文的「老」字，画的是一个驼背、长头发、手里拄着拐杖的老人。本义就是年老、老人。因为老人经验丰富，所以「老」也表示「老练」「陈旧」等意思。比如「老人」「老年」「老练」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「老」條；香港中文大學《漢語多功能字庫》「老」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%81（2026-11-03 查閱）"},
  "19397_者_Z_說文‧𦣹部": {"headline": "「者」是一个指代名词，本义不太清楚。", "original_meaning": "「者」的本义不明，常用作代词、助词。", "structure_desc": "「者」字的构形本义，学者们还没有定论。金文的「者」从「木」从几点从「口」，可能和祭祀或陈列有关。后来「者」被用作代词和助词，比如「作者」「读者」「或者」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「者」條；香港中文大學《漢語多功能字庫》「者」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%85（2026-11-03 查閱）"},
  "19404_而_Z_說文‧而部": {"headline": "「而」就是下巴上的胡子。", "original_meaning": "「而」的本义是颊毛、胡须，后来作连词。", "structure_desc": "「而」字像下巴上的胡须，上面加一短横是装饰笔。本义是胡须。后来「而」被借用作连词，表示「而且」「然而」等意思，人们就另造了字来表示胡须。比如「而且」「然而」「因而」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「而」條；香港中文大學《漢語多功能字庫》「而」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%8C（2026-11-03 查閱）"},
  "19645_能_Z_說文‧能部": {"headline": "「能」本来是一只大熊。", "original_meaning": "「能」的本义是熊，引申为能力、能够。", "structure_desc": "「能」字本来画的是一只熊，是「熊」的本字。因为熊很有力气，所以「能」引申出「能力」「能够」的意思。后来人们另造了「熊」字表示动物，「能」就专门表示能力了。比如「能力」「能够」「才能」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「能」條；香港中文大學《漢語多功能字庫》「能」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%83%BD（2026-11-03 查閱）"},
  "19882_自_Z_說文‧自部": {"headline": "「自」就是一只鼻子。", "original_meaning": "「自」的本义是鼻子，后来表示自己。", "structure_desc": "甲骨文和金文的「自」字，画的是一只鼻子，中间两横像鼻子上的皱纹。本义是鼻子。后来人们说「我自己」的时候，习惯用手指着自己的鼻子，所以「自」就引申出「自己」的意思。比如「自己」「自然」「自由」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「自」條；香港中文大學《漢語多功能字庫》「自」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%87%AA（2026-11-03 查閱）"},
  "21516_行_Z_說文‧行部": {"headline": "「行」就是四通八达的十字路口。", "original_meaning": "「行」的本义是道路，引申为行走。", "structure_desc": "甲骨文和金文的「行」字，画的是一个四通八达的十字路口。本义是道路。因为路是人走出来的，所以「行」引申出「行走」的意思。「行」作偏旁时常常写作「彳」，很多和走路有关的字都带「彳」。比如「行走」「行动」「旅行」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「行」條；香港中文大學《漢語多功能字庫》「行」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%8C（2026-11-03 查閱）"},
  "21544_表_Z_說文‧衣部": {"headline": "「表」就是外面带毛的皮衣。", "original_meaning": "「表」的本义是外衣，引申为外表、表示。", "structure_desc": "「表」从「衣」从「毛」，表示衣服外面带毛，也就是皮衣的外面。本义是外衣、外表。因为外衣是露在外面的，所以「表」引申出「表面」「表示」「表达」等意思。比如「表面」「表示」「表达」「手表」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「表」條；香港中文大學《漢語多功能字庫》「表」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%A8（2026-11-03 查閱）"},
  "21825_要_Z_說文‧𦥑部": {"headline": "「要」就是人双手叉着腰。", "original_meaning": "「要」的本义是腰部，引申为主要、需要。", "structure_desc": "古文字的「要」字，上面是「目」（代表头），中间是「大」（人），下面是双手叉腰的样子。本义是腰部（是「腰」的本字）。因为腰是身体的中间、关键部位，所以「要」引申出「主要」「重要」「需要」等意思。比如「重要」「需要」「要点」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「要」條；香港中文大學《漢語多功能字庫》「要」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%81（2026-11-03 查閱）"},
  "21889_见_Z_小篆": {"headline": "「见」就是一个人睁大了眼睛看。", "original_meaning": "「见」的本义是看见、看到。", "structure_desc": "「见」的繁体是「見」，甲骨文和金文从「目」从「卩」（一个跪坐的人），突出人的大眼睛，表示看见。本义就是看见、看到。比如「看见」「见面」「意见」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「見」條；香港中文大學《漢語多功能字庫》「見」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%8B（2026-11-03 查閱）"},
  "22452_说_Z_小篆": {"headline": "「说」就是用言语把话讲出来。", "original_meaning": "「说」的本义是讲述、解释。", "structure_desc": "「说」的繁体是「說」，从「言」，「兑」表音。本义是用言语讲述、解释。后来「说」引申出「说法」「说服」等意思。古文中「说」还可以表示「悦」（高兴），比如「学而时习之，不亦说乎」。比如「说话」「说明」「小说」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「說」條；香港中文大學《漢語多功能字庫》「說」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%AA%AA（2026-11-03 查閱）"},
  "22839_起_Z_說文‧走部": {"headline": "「起」就是从座位上站起来。", "original_meaning": "「起」的本义是起立、站起。", "structure_desc": "「起」从「走」（表示行走），「巳」表音。本义是站起来、起立。后来「起」引申出「开始」「兴起」「起床」等意思。比如「起立」「起床」「起来」「兴起」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「起」條；香港中文大學《漢語多功能字庫》「起」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B5%B7（2026-11-03 查閱）"},
  "23431_过_Z_小篆": {"headline": "「过」就是渡过水面、走过去。", "original_meaning": "「过」的本义是渡过、经过。", "structure_desc": "「过」的繁体是「過」，从「辵」（表示行走），「呙」表音。本义是渡过、经过。后来「过」引申出「过去」「超过」「过错」等意思。比如「经过」「过去」「超过」「过错」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「過」條；香港中文大學《漢語多功能字庫》「過」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%8E（2026-11-03 查閱）"},
  "23448_还_Z_小篆": {"headline": "「还」就是沿着圆形的路走回来。", "original_meaning": "「还」的本义是返回、归还。", "structure_desc": "「还」的繁体是「還」，从「辵」（表示行走），「睘」表音。「睘」本义是圆形的玉璧，圆的东西有回转的意思，加上「辵」表示行走，合起来就是走回来的意思。本义是返回、归还。后来「还」又表示「还是」「还有」等意思。比如「还有」「还是」「归还」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𨘣」條（今字作「還」）；香港中文大學《漢語多功能字庫》「還」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%82%84（2026-11-03 查閱）"},
  "23451_进_Z_小篆": {"headline": "「进」就是像鸟一样只能往前走。", "original_meaning": "「进」的本义是前进、向前走。", "structure_desc": "「进」的繁体是「進」，甲骨文从「隹」（短尾巴的鸟）从「止」（脚），表示鸟在往前走。因为鸟只会往前走不会后退，所以「进」有前进的意思。后来加上「辵」（行走），表示向前走。比如「前进」「进步」「进入」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「進」條；香港中文大學《漢語多功能字庫》「進」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%B2（2026-11-03 查閱）"},
  "23571_道_Z_說文‧辵部": {"headline": "「道」就是人走在大路上。", "original_meaning": "「道」的本义是道路，引申为道理、道德。", "structure_desc": "「道」从「首」（人头）从「止」（脚），表示人在走路。古文字的「首」和「止」合起来代表人，整个字画的是一个人走在道路上。本义是道路。因为走路要有路，做人也要有原则，所以「道」引申出「道理」「道德」等意思。比如「道路」「道理」「道德」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「道」條；香港中文大學《漢語多功能字庫》「道」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%93（2026-11-03 查閱）"},
  "23651_那_Z_說文‧邑部": {"headline": "「那」就是指比较远的人或东西。", "original_meaning": "「那」的本义是指代较远的事物，与「这」相对。", "structure_desc": "「那」从「邑」（表示地方），「冉」表音。《说文解字》说「那」是古代的一个国名。后来「那」被借用作指示代词，指代比较远的人或事物，和「这」相对。比如「那里」「那个」「那样」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「𨙻」條（今字作「那」）；香港中文大學《漢語多功能字庫》「那」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%82%A3（2026-11-03 查閱）"},
  "23720_部_Z_說文‧邑部": {"headline": "「部」就是按地域划分的区域。", "original_meaning": "「部」的本义是古地名，引申为部门、部分。", "structure_desc": "「部」从「邑」（表示地方），「咅」表音。本义是古代的一个地名。后来「部」引申出「部分」「部门」「部位」等意思，指整体中的一个组成部分。比如「部分」「部门」「部位」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「部」條；香港中文大學《漢語多功能字庫》「部」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%83%A8（2026-11-03 查閱）"},
  "23741_都_Z_說文‧邑部": {"headline": "「都」就是有宗庙的大城市。", "original_meaning": "「都」的本义是都城、大城市。", "structure_desc": "「都」从「邑」（表示城邑），「者」表音。《说文解字》说，有先王宗庙的城邑叫「都」。本义是都城、大城市。后来「都」也作副词，表示「全部」，比如「都是」「都好」。比如「首都」「都市」「都是」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「都」條；香港中文大學《漢語多功能字庫》「都」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%83%BD（2026-11-03 查閱）"},
  "23948_里_Z_說文‧里部": {"headline": "「里」就是有田有土的村庄。", "original_meaning": "「里」的本义是人们聚居的地方，也表示内部。", "structure_desc": "「里」从「田」从「土」，表示有田有土可以居住的地方。本义是古代村民聚居的村庄。后来「里」也表示长度单位（一里路），还和「裏」合并，表示「里面」的意思。比如「里外」「里面」「公里」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「里」條；香港中文大學《漢語多功能字庫》「里」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8C（2026-11-03 查閱）"},
  "23949_重_Z_說文‧重部": {"headline": "「重」就是人背着一个大口袋。", "original_meaning": "「重」的本义是沉重、分量大。", "structure_desc": "甲骨文和金文的「重」字，上面是「人」，下面是「東」（像一个大口袋），合起来就是一个人背着大口袋的样子。背着口袋当然很沉，所以「重」的本义是沉重。后来「重」引申出「重要」「重视」等意思。比如「沉重」「重要」「重视」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「重」條；香港中文大學《漢語多功能字庫》「重」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8D（2026-11-03 查閱）"},
  "23951_量_Z_說文‧重部": {"headline": "「量」就是在太阳下量东西。", "original_meaning": "「量」的本义是衡量、量度。", "structure_desc": "甲骨文和金文的「量」字从「日」从「東」（像口袋），一说表示在太阳底下量度东西。本义是衡量、量度。后来「量」引申出「数量」「容量」等意思。比如「测量」「数量」「力量」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「量」條；香港中文大學《漢語多功能字庫》「量」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8F（2026-11-03 查閱）"},
  "24895_长_Z_小篆": {"headline": "「长」就是拄着拐杖的长发老人。", "original_meaning": "「长」的本义是年长、长者，引申为长短的长。", "structure_desc": "「长」的繁体是「長」，甲骨文和金文字形象一个长头发的老人拄着拐杖。本义是年长、长者。因为老人的头发很长，所以「长」引申出「长短」的「长」。比如「长短」「长久」「长辈」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「長」條；香港中文大學《漢語多功能字庫》「長」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%95%B7（2026-11-03 查閱）"},
  "25006_问_Z_小篆": {"headline": "「问」就是在门口开口问话。", "original_meaning": "「问」的本义是询问、提问。", "structure_desc": "「问」的繁体是「問」，从「口」，「门」表音。甲骨文和金文从「门」从「口」，表示在门口开口问话。本义是询问、提问。比如「问题」「提问」「问候」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「問」條；香港中文大學《漢語多功能字庫》「問」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%95%8F（2026-11-03 查閱）"},
  "25012_间_Z_小篆": {"headline": "「间」就是月光从门缝里照进来。", "original_meaning": "「间」的本义是门缝、空隙。", "structure_desc": "「间」的繁体是「間」，本作「閒」，从「门」从「月」，表示月光从门缝里照进来。本义是门缝、空隙。后来「间」引申出「中间」「间隔」「房间」等意思。比如「中间」「间隔」「房间」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「閒」條（今字作「間」）；香港中文大學《漢語多功能字庫》「間」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%96%93（2026-11-03 查閱）"},
  "25378_面_Z_說文‧面部": {"headline": "「面」就是一张脸，中间是眼睛。", "original_meaning": "「面」的本义是脸、颜面。", "structure_desc": "甲骨文的「面」字，外面是脸的轮廓，中间是一只眼睛（目）。本义是脸、颜面。后来「面」引申出「表面」「面向」「面条」等意思。比如「面孔」「表面」「面向」「面条」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「面」條；香港中文大學《漢語多功能字庫》「面」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9D%A2（2026-11-03 查閱）"},
  "26264_高_Z_說文‧高部": {"headline": "「高」就是建在台基上的高楼。", "original_meaning": "「高」的本义是高大的楼台，引申为高低的高。", "structure_desc": "甲骨文和金文的「高」字，画的是建在高高的台基上的楼台。本义是高大的楼台。后来「高」引申出「高低」「高大」「高尚」等意思。比如「高大」「高低」「高尚」「高兴」。", "source": "《說文解字》（中華書局1963年影印陳昌治校刊本）「高」條；香港中文大學《漢語多功能字庫》「高」條：https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%AB%98（2026-11-03 查閱）"},
};
